function estimateSuiteRuntimeMs(counts, perTestMs) {
  return (
    counts.unitCount * perTestMs.unitMs +
    counts.integrationCount * perTestMs.integrationMs +
    counts.e2eCount * perTestMs.e2eMs
  );
}

function totalRuntimeSeconds(counts, perTestSeconds) {
  return (
    counts.unit * perTestSeconds.unit +
    counts.integration * perTestSeconds.integration +
    counts.e2e * perTestSeconds.e2e
  );
}

function slowestLevel(counts, perTestMs) {
  const totals = {
    unit: counts.unitCount * perTestMs.unitMs,
    integration: counts.integrationCount * perTestMs.integrationMs,
    e2e: counts.e2eCount * perTestMs.e2eMs,
  };
  return Object.entries(totals).sort((a, b) => b[1] - a[1])[0][0];
}

function runDiscountEdgeCases(applyDiscount) {
  const zeroDiscount = applyDiscount(100, 0);
  const fullDiscount = applyDiscount(100, 100);
  let overRange = false;
  try {
    applyDiscount(100, 150);
  } catch (e) {
    overRange = true;
  }
  return { zeroDiscount, fullDiscount, overRange };
}
